import * as THREE from './assets/three.module.js';
const canvas=document.querySelector('#scene'),stage=document.querySelector('#stage');
try{
const renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x0f0e11,0);renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.55;
const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(35,1,.1,100);camera.position.set(0,0,10);
scene.add(new THREE.HemisphereLight(0xffffff,0x333344,2.8));const light=new THREE.DirectionalLight(0xffeee0,5);light.position.set(-3,5,5);scene.add(light);const fill=new THREE.DirectionalLight(0xffffff,3);fill.position.set(5,-1,2);scene.add(fill);
const orange=new THREE.MeshPhysicalMaterial({color:0xf7bacc,metalness:.35,roughness:.25,clearcoat:1,clearcoatRoughness:.2});const dark=new THREE.MeshStandardMaterial({color:0x37323d,metalness:.85,roughness:.27});const silver=new THREE.MeshStandardMaterial({color:0xd5d7da,metalness:.8,roughness:.22});
const root=new THREE.Group();scene.add(root);root.rotation.set(.2,-.35,-.15);
const models={play:new THREE.Group(),reel:new THREE.Group(),frames:new THREE.Group()};Object.values(models).forEach(m=>root.add(m));
const shape=new THREE.Shape();shape.moveTo(-1.5,-1.7);shape.lineTo(-1.5,1.7);shape.quadraticCurveTo(-1.5,1.95,-1.25,1.8);shape.lineTo(1.75,.16);shape.quadraticCurveTo(2,0,1.75,-.16);shape.lineTo(-1.25,-1.8);shape.quadraticCurveTo(-1.5,-1.95,-1.5,-1.7);const hole=new THREE.Path();hole.moveTo(-.7,-.75);hole.lineTo(.67,0);hole.lineTo(-.7,.75);hole.closePath();shape.holes.push(hole);
const play=new THREE.Mesh(new THREE.ExtrudeGeometry(shape,{depth:.52,bevelEnabled:true,bevelThickness:.14,bevelSize:.12,bevelSegments:6,steps:1,curveSegments:32}),orange);play.position.z=-.3;models.play.add(play);
const orbit=new THREE.Mesh(new THREE.TorusGeometry(2.45,.035,12,120),dark);orbit.rotation.x=.6;orbit.rotation.y=.3;models.play.add(orbit);const orb=new THREE.Mesh(new THREE.SphereGeometry(.25,32,20),silver);orb.position.set(1.7,1.8,.2);models.play.add(orb);
function reel(group,x,y,z,r,mat){const disk=new THREE.Mesh(new THREE.CylinderGeometry(r,r,.3,64),mat);disk.rotation.x=Math.PI/2;disk.position.set(x,y,z);group.add(disk);const hub=new THREE.Mesh(new THREE.CylinderGeometry(r*.18,r*.18,.38,32),silver);hub.rotation.x=Math.PI/2;hub.position.set(x,y,z+.1);group.add(hub);for(let i=0;i<5;i++){const a=i*Math.PI*2/5;const hole=new THREE.Mesh(new THREE.CylinderGeometry(r*.2,r*.2,.03,32),dark);hole.rotation.x=Math.PI/2;hole.position.set(x+Math.cos(a)*r*.58,y+Math.sin(a)*r*.58,z+.166);group.add(hole)}}
reel(models.reel,-.65,.5,.1,1.55,orange);reel(models.reel,1,-.8,-.4,1.15,silver);
for(let i=0;i<3;i++){const frame=new THREE.Group();const border=new THREE.Mesh(new THREE.BoxGeometry(2.5,3.3,.22),i===2?orange:dark);frame.add(border);const inset=new THREE.Mesh(new THREE.BoxGeometry(2.1,2.35,.24),i===2?dark:silver);inset.position.y=.1;frame.add(inset);const sign=play.clone();sign.scale.setScalar(.34);sign.position.set(.1,.15,.2);frame.add(sign);frame.position.set((i-1)*.65,(i-1)*.35,(i-1)*.55);frame.rotation.z=(i-1)*-.16;models.frames.add(frame)}
let current='play',running=false,visible=true,drag=false,lastX=0,lastY=0;Object.entries(models).forEach(([k,m])=>m.visible=k===current);const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const draw=()=>renderer.render(scene,camera);const resize=()=>{const w=stage.clientWidth,h=stage.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.position.z=w<360?11.5:10;camera.updateProjectionMatrix();draw()};new ResizeObserver(resize).observe(stage);resize();stage.classList.add('loaded');canvas.tabIndex=0;
const toggle=document.querySelector('#rotate');toggle.addEventListener('click',()=>{running=!running;toggle.textContent=running?'Остановить':'Вращать модель';toggle.setAttribute('aria-pressed',String(running))});
document.querySelectorAll('[data-model]').forEach(b=>b.addEventListener('click',()=>{current=b.dataset.model;Object.entries(models).forEach(([k,m])=>m.visible=k===current);document.querySelectorAll('[data-model]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelector('#scene-label').textContent={play:'Play, объём и немного магии',reel:'История начинается с катушки',frames:'Каждый кадр на своём месте'}[current];draw()}));
canvas.addEventListener('pointerdown',e=>{drag=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drag)return;root.rotation.y+=(e.clientX-lastX)*.01;root.rotation.x+=(e.clientY-lastY)*.01;lastX=e.clientX;lastY=e.clientY;draw()});canvas.addEventListener('pointerup',()=>drag=false);canvas.addEventListener('pointercancel',()=>drag=false);canvas.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();root.rotation.y+=e.key==='ArrowLeft'?-.15:e.key==='ArrowRight'?.15:0;root.rotation.x+=e.key==='ArrowUp'?-.15:e.key==='ArrowDown'?.15:0;draw()});
new IntersectionObserver(([e])=>visible=e.isIntersecting).observe(stage);stage.addEventListener('pointerenter',()=>stage.dataset.hover='yes');stage.addEventListener('pointerleave',()=>delete stage.dataset.hover);let previous=0;renderer.setAnimationLoop(t=>{const dt=Math.min((t-previous)/1000,.05);previous=t;if(running&&visible&&!reduced.matches&&!document.hidden&&!stage.dataset.hover&&!stage.contains(document.activeElement)){root.rotation.y+=dt*.3;draw()}});window.__sceneReady=true;
}catch(e){document.querySelector('#scene-label').textContent='3D недоступно в этом браузере';document.querySelector('#rotate').disabled=true;document.querySelectorAll('[data-model]').forEach(b=>b.disabled=true);console.warn('3D fallback',e)}
